// Compare the scraped products with the rows already in the sheet.
// The product URL is the unique key: a product whose URL is already in the
// sheet is skipped, so running the workflow twice never creates duplicates.

const scraped = $('Scrape products').first().json;
const existingUrls = new Set(
  $('Read existing rows').all()
    .map(item => String(item.json.url || '').trim())
    .filter(url => url !== '')
);

const now = new Date().toISOString();
const newRows = [];

for (const p of scraped.products || []) {
  if (existingUrls.has(p.url)) continue;   // already in the sheet -> skip
  newRows.push({
    json: {
      id: p.id,
      title: p.title,
      product_type: p.product_type,
      price: p.price,
      url: p.url,
      image_urls: (p.images || []).map(img => img.src).join('\n'),
      description_en: p.description_en,
      dimensions_en: p.dimensions,
      material_construction_en: p.material_construction,
      features_feel_en: p.features_feel,
      description_de: '',
      dimensions_de: '',
      material_construction_de: '',
      features_feel_de: '',
      status: 'Neu',
      approval: '',
      error: '',
      created_at: now,
      updated_at: now,
    },
  });
}

// Returning an empty list stops the workflow here: nothing new to do.
return newRows;

