// Read the JSON answer from OpenAI and build the sheet update for this product.
const row = $('Keep only new products').item.json;
const now = new Date().toISOString();

try {
  const t = JSON.parse($json.choices[0].message.content);
  return {
    json: {
      id: row.id,                      // used to find the right row in the sheet
      description_de: t.description_de || '',
      dimensions_de: t.dimensions_de || '',
      material_construction_de: t.material_construction_de || '',
      features_feel_de: t.features_feel_de || '',
      status: 'Wartet auf Freigabe',
      error: '',
      updated_at: now,
    },
  };
} catch (e) {
  // OpenAI answered, but not with the JSON we expected
  return {
    json: { id: row.id, status: 'Fehler', error: 'Translation could not be read: ' + e.message, updated_at: now },
  };
}

// The OpenAI request failed (no credit, wrong key, timeout, ...).
// Mark the product as "Fehler" and keep the reason in the error column.
const row = $('Keep only new products').item.json;
const err = $json.error;
const message = typeof err === 'string' ? err : (err && err.message) || JSON.stringify($json);

return {
  json: {
    id: row.id,
    status: 'Fehler',
    error: ('Translation failed: ' + message).slice(0, 500),
    updated_at: new Date().toISOString(),
  },
};
